public static void main(String[] args) {
    try (Scanner sc = new Scanner(System.in)) {
        int n = sc.nextInt();
        long[] a = new long[n];
        a[0] = sc.nextLong();
        long min = a[0];
        for (int i = 1; i < n; i++) {
            a[i] = sc.nextLong() + a[i - 1];
            if (min > a[i])
                min = a[i];
        }
        System.out.println(Math.max(0, a[n - 1] - min));
    }
}
